function draw(ctx, t, p) {
  const W=960,H=540,TAU=Math.PI*2;
  const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
  const n=(v,d)=>Number.isFinite(Number(v))?Number(v):d;
  const fmt=(v,k=3)=>Number.isFinite(v)?v.toFixed(k):"不存在";
  const lerp=(a,b,u)=>a+(b-a)*u;
  const x0raw=clamp(n(p.x0,1),-2,2);
  const mag=clamp(n(p.h,.5),.02,2);
  const side=n(p.side,1)<0?-1:1;
  const example=n(p.example,0)>=.5?1:0;
  const ends=[8,22,36,50,64,78], total=78;
  const sec=clamp(n(t,0),0,1)*total;
  let si=0; while(si<5&&sec>=ends[si])si++;
  const start=si?ends[si-1]:0, local=clamp((sec-start)/(ends[si]-start),0,1);
  const main=true;
  const isAbs=si===5;
  const x0=isAbs?0:x0raw;
  const f=x=>isAbs?Math.abs(x):x*x;
  const der=isAbs?NaN:2*x0;
  let h;
  if(si===2) h=side*lerp(1,.02,local);
  else h=side*mag;
  const qx=x0+h, fp=f(x0), fq=f(qx);
  const slope=Math.abs(h)>1e-12?(fq-fp)/h:NaN;
  const residual=isAbs?NaN:fq-(fp+der*h);
  ctx.fillStyle="#f7fafc";ctx.fillRect(0,0,W,H);
  ctx.fillStyle="#18324a";ctx.font="bold 23px sans-serif";ctx.fillText("割线旋转成切线：导数的极限定义",35,42);
  ctx.font="17px sans-serif";ctx.fillStyle="#5a7286";ctx.fillText("h ≠ 0；总时长 78 秒",748,42);
  const GX0=45,GX1=620,GY0=95,GY1=415,xmin=-4.6,xmax=4.6,ymin=-1.2,ymax=17;
  const X=x=>GX0+(x-xmin)/(xmax-xmin)*(GX1-GX0);
  const Y=y=>GY1-(y-ymin)/(ymax-ymin)*(GY1-GY0);
  ctx.fillStyle="#fff";ctx.fillRect(GX0,GY0,GX1-GX0,GY1-GY0);
  ctx.strokeStyle="#d6e4ed";ctx.strokeRect(GX0+.5,GY0+.5,GX1-GX0-1,GY1-GY0-1);
  ctx.strokeStyle="#e8f1f6";ctx.lineWidth=1;
  for(let z=-4;z<=4;z++){ctx.beginPath();ctx.moveTo(X(z),GY0);ctx.lineTo(X(z),GY1);ctx.stroke();}
  for(let z=0;z<=16;z+=2){ctx.beginPath();ctx.moveTo(GX0,Y(z));ctx.lineTo(GX1,Y(z));ctx.stroke();}
  ctx.strokeStyle="#365a72";ctx.lineWidth=2;
  ctx.beginPath();ctx.moveTo(GX0,Y(0));ctx.lineTo(GX1,Y(0));ctx.stroke();
  ctx.beginPath();ctx.moveTo(X(0),GY1);ctx.lineTo(X(0),GY0);ctx.stroke();
  ctx.fillStyle="#365a72";ctx.font="15px sans-serif";
  for(let z=-4;z<=4;z++){if(z){ctx.fillText(String(z),X(z)-5,Y(0)+20);}}
  for(let z=2;z<=16;z+=4)ctx.fillText(String(z),X(0)+8,Y(z)+5);
  ctx.font="bold 16px sans-serif";ctx.fillText("x",GX1-14,Y(0)-10);ctx.fillText("y",X(0)+10,GY0+16);
  function clip(){ctx.beginPath();ctx.rect(GX0,GY0,GX1-GX0,GY1-GY0);ctx.clip();}
  function seg(a,b,c,d,col,w=2,dash=[]){ctx.save();clip();ctx.strokeStyle=col;ctx.lineWidth=w;ctx.setLineDash(dash);ctx.beginPath();ctx.moveTo(X(a),Y(b));ctx.lineTo(X(c),Y(d));ctx.stroke();ctx.restore();}
  function dot(a,b,col,r=6){ctx.save();clip();ctx.fillStyle=col;ctx.beginPath();ctx.arc(X(a),Y(b),r,0,TAU);ctx.fill();ctx.restore();}
  function label(a,b,s,col,dx=8,dy=-8){ctx.save();ctx.fillStyle=col;ctx.font="bold 17px sans-serif";ctx.fillText(s,clamp(X(a)+dx,GX0+4,GX1-55),clamp(Y(b)+dy,GY0+20,GY1-6));ctx.restore();}
  ctx.save();clip();ctx.strokeStyle="#236fb5";ctx.lineWidth=3.5;ctx.beginPath();
  for(let i=0;i<=420;i++){const xx=xmin+(xmax-xmin)*i/420, yy=f(xx);i?ctx.lineTo(X(xx),Y(yy)):ctx.moveTo(X(xx),Y(yy));}ctx.stroke();ctx.restore();
  if(si>=2&&!isAbs)seg(xmin,fp+der*(xmin-x0),xmax,fp+der*(xmax-x0),"#9b55b6",2,[8,6]);
  if(si===3||si===5){
    seg(x0,fp,x0-mag,f(x0-mag),side<0?"#d84b4b":"#efb2b2",side<0?3:2);
    seg(x0,fp,x0+mag,f(x0+mag),side>0?"#168c70":"#9bd7c5",side>0?3:2);
  }else{
    seg(x0,fp,qx,fp,"#e58b32",2,[6,5]);seg(qx,fp,qx,fq,"#e58b32",2,[6,5]);seg(x0,fp,qx,fq,"#7a4aa8",3);
  }
  if(si===4&&!isAbs)seg(qx,fp+der*h,qx,fq,"#d84b4b",4);
  dot(x0,fp,"#f28e2b",7);label(x0,fp,"P","#a3591a");
  if(si===3||si===5){dot(x0-mag,f(x0-mag),"#d84b4b",6);dot(x0+mag,f(x0+mag),"#168c70",6);label(x0-mag,f(x0-mag),"Q−","#a02c20",-35);label(x0+mag,f(x0+mag),"Q+","#14614a");}
  else{dot(qx,fq,"#7a4aa8",6);label(qx,fq,"Q","#5c3480");}
  ctx.font="16px sans-serif";ctx.fillStyle="#236fb5";ctx.fillText("▬ 蓝：曲线",45,86);ctx.fillStyle="#e58b32";ctx.fillText("▬ 橙：增量",165,86);ctx.fillStyle="#7a4aa8";ctx.fillText("▬ 紫：割线/切线",285,86);
  const BX=636,BY=90,BW=286,BH=330;ctx.fillStyle="#eef5fa";ctx.fillRect(BX,BY,BW,BH);ctx.strokeStyle="#c6d9e5";ctx.strokeRect(BX+.5,BY+.5,BW-1,BH-1);
  const titles=["固定点与附近的动点","用增量构造割线斜率","从右侧逼近切线","左右极限必须一致","切线为何能近似曲线","连续的尖点为何不可导"];
  ctx.fillStyle="#18324a";ctx.font="bold 18px sans-serif";ctx.fillText("S"+(si+1)+" "+titles[si],BX+14,BY+32);ctx.strokeStyle="#c6d9e5";ctx.beginPath();ctx.moveTo(BX+12,BY+46);ctx.lineTo(BX+BW-12,BY+46);ctx.stroke();
  let rows=[];
  if(isAbs){
    rows=["f(x)=|x|，x₀ = 0（尖点）","|h| = "+fmt(mag,2)+"；选中方向 h = "+(side>0?"+":"−")+"|h|","m(+|h|) = +1.000","m(−|h|) = −1.000","左右极限不相等","连续但不可导"];
  }else{
    rows=["f(x)=x²，x₀ = "+fmt(x0,2),"h = "+(h>0?"+":"−")+fmt(Math.abs(h),3),"m(h) = "+fmt(slope,4),"m(+|h|) = "+fmt(2*x0+mag,4),"m(−|h|) = "+fmt(2*x0-mag,4),"f′(x₀)=2x₀ = "+fmt(der,3)];
    if(si===4)rows=["x₀ = "+fmt(x0,2),"|h| = "+fmt(Math.abs(h),4),"误差 r(h)=h² = "+fmt(Math.abs(residual),6),"r(h)/|h| = "+fmt(Math.abs(residual)/Math.abs(h),6),"|h| 越小，误差比越趋近 0","L(x)=x₀²+2x₀(x−x₀)"];
  }
  ctx.font="17px sans-serif";ctx.fillStyle="#2f4a5e";for(let i=0;i<rows.length;i++)ctx.fillText(rows[i],BX+14,BY+76+i*28);
  ctx.strokeStyle="#c6d9e5";ctx.beginPath();ctx.moveTo(BX+12,BY+236);ctx.lineTo(BX+BW-12,BY+236);ctx.stroke();ctx.fillStyle="#7a4aa8";ctx.font="17px sans-serif";
  const formulas=isAbs?["m(h)=|h|/h","h>0→1，h<0→−1","f′(0) 不存在"]:si===4?["f(x₀+h)=x₀²+2x₀h+h²","f(x₀+h)−L(x₀+h)=h²","h²/|h|=|h|→0"]:["m(h)=[f(x₀+h)−f(x₀)]/h","[(x₀+h)²−x₀²]/h=2x₀+h","左右极限相同，f′(x₀)=2x₀"];
  for(let i=0;i<formulas.length;i++)ctx.fillText(formulas[i],BX+14,BY+262+i*28);
  return {metrics:{scene:si+1,elapsedSeconds:Number(sec.toFixed(3)),x0:Number(x0.toFixed(4)),h:Number(h.toFixed(5)),slope:Number.isFinite(slope)?Number(slope.toFixed(5)):"不存在",derivative:Number.isFinite(der)?Number(der.toFixed(4)):"不存在",residual:Number.isFinite(residual)?Number(residual.toFixed(6)):"不适用",example:isAbs?"|x|":"x²",selectedSide:side}};
}
